def test_worker_execute_uses_batch_size():
    # task should contain batch_size from payload
    task = {'owner': 'wo', 'batch_size': 25}
    def process(owner, bs):
        return f'{owner}:{bs}'
    result = execute(task, process)
    assert result == 'wo:25'

def test_worker_execute_fallback_to_20():
    # legacy queued payloads without batch_size use 20
    task = {'owner': 'lo'}
    def process(owner, bs):
        return f'{owner}:{bs}'
    # execute should get batch_size from task.get('batch_size',20)
    result = execute(task, process)
    assert result == 'lo:20'

